&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;307 200 PX&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Type-Dragon.html&quot; title=&quot;Dragon&quot;&gt;Dragon&lt;/a&gt; de taille Gig, N&lt;/li&gt;&lt;li&gt;&lt;b&gt;Init &lt;/b&gt;+14 ; &lt;b&gt;Sens &lt;/b&gt;d&#233;tection de la magie, sens draconiques, vision dans les t&#233;n&#232;bres ; Perception +36&lt;/li&gt;&lt;li&gt;&lt;b&gt;Aura &lt;/b&gt;pr&#233;sence &#233;trang&#232;re (90 m, DD 29)&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;D&#233;fense&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;CA &lt;/b&gt;37, contact 6, pris au d&#233;pourvu 37 (naturelle +31, taille -4)&lt;/li&gt;&lt;li&gt;&lt;b&gt;pv &lt;/b&gt;418 (27d12+243)&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;f &lt;/b&gt;+17, &lt;b&gt;Vig &lt;/b&gt;+24, &lt;b&gt;Vol&lt;/b&gt; +21&lt;/li&gt;&lt;li&gt;&lt;b&gt;RD &lt;/b&gt;15/magie; &lt;b&gt;Immunit&#233;s &lt;/b&gt;chancelant, froid, paralysie, sommeil ; &lt;b&gt;RM &lt;/b&gt;31&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Attaque&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;VD &lt;/b&gt;15 m, vol 75 m (d&#233;plorable)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Corps &#224; corps &lt;/b&gt;morsure, +38 (4d6+21)&lt;ul&gt;&lt;li&gt;et 2 griffes, +38 (2d8+14/19-20)&lt;/li&gt;&lt;li&gt;et 2 ailes, +35 (2d6+7)&lt;/li&gt;&lt;li&gt;et coup de queue, +35 (2d8+21)&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Espace &lt;/b&gt;6 m ; &lt;b&gt;Allonge &lt;/b&gt;4,50 m (6 m avec la morsure)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaque sp&#233;ciale&lt;/b&gt; balayage de la queue, &#233;crasement, seconde chance, souffle (c&#244;ne de 18 m, 20d10 &#233;lectricit&#233;, DD 32), souffle de saut temporel (5 rounds)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Pouvoirs magiques&lt;/b&gt; (&lt;b&gt;NLS &lt;/b&gt;27 ; concentration +33)&lt;ul&gt;&lt;li&gt;&lt;i&gt;Constant &lt;/i&gt;— &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Magie.html&quot; title=&quot;D&#233;tection de la magie&quot;&gt;d&#233;tection de la magie&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;&#192; volont&#233; &lt;/i&gt;— &lt;a class=&quot;pagelink&quot; href=&quot;Clairaudienceclairvoyance.html&quot; title=&quot;Clairaudience/clairvoyance&quot;&gt;clairaudience/clairvoyance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Localisation-De-Cr&#233;ature.html&quot; title=&quot;Localisation de cr&#233;ature&quot;&gt;localisation de cr&#233;ature&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mythes-Et-L&#233;gendes.html&quot; title=&quot;Mythes et l&#233;gendes&quot;&gt;mythes et l&#233;gendes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Partage-Des-Souvenirs.html&quot; title=&quot;Partage des souvenirs&quot;&gt;partage des souvenirs&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Sorts d’ensorceleur connus&lt;/b&gt; (&lt;b&gt;NLS &lt;/b&gt;15 ; concentration +21)&lt;ul&gt;&lt;li&gt;&lt;i&gt;7&#232;me (4/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Changement-De-Plan.html&quot; title=&quot;Changement de plan&quot;&gt;changement de plan&lt;/a&gt; (DD 23), &lt;a class=&quot;pagelink&quot; href=&quot;Dissimulation-Supr&#234;me.html&quot; title=&quot;Dissimulation supr&#234;me&quot;&gt;dissimulation supr&#234;me&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt; 6&#232;me (7/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;sint&#233;gration.html&quot; title=&quot;D&#233;sint&#233;gration&quot;&gt;d&#233;sint&#233;gration&lt;/a&gt; (DD 22), &lt;a class=&quot;pagelink&quot; href=&quot;Dissipation-Supr&#234;me.html&quot; title=&quot;Dissipation supr&#234;me&quot;&gt;dissipation supr&#234;me&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Lucide.html&quot; title=&quot;Vision lucide&quot;&gt;vision lucide&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;5&#232;me (7/jour) &lt;/i&gt;— &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;bilit&#233;.html&quot; title=&quot;D&#233;bilit&#233;&quot;&gt;d&#233;bilit&#233;&lt;/a&gt; (DD 21), &lt;a class=&quot;pagelink&quot; href=&quot;Domination.html&quot; title=&quot;Domination&quot;&gt;domination&lt;/a&gt; (DD 21), &lt;a class=&quot;pagelink&quot; href=&quot;Lien-T&#233;l&#233;pathique.html&quot; title=&quot;Lien t&#233;l&#233;pathique&quot;&gt;lien t&#233;l&#233;pathique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;T&#233;l&#233;portation.html&quot; title=&quot;T&#233;l&#233;portation&quot;&gt;t&#233;l&#233;portation&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;4&#232;me (7/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Fa&#231;onnage-De-La-Pierre.html&quot; title=&quot;Fa&#231;onnage de la pierre&quot;&gt;fa&#231;onnage de la pierre&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Peau-De-Pierre.html&quot; title=&quot;Peau de pierre&quot;&gt;peau de pierre&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Scrutation.html&quot; title=&quot;Scrutation&quot;&gt;scrutation&lt;/a&gt; (DD 20), &lt;a class=&quot;pagelink&quot; href=&quot;Terreur.html&quot; title=&quot;Terreur&quot;&gt;terreur&lt;/a&gt; (DD 20)&lt;/li&gt;&lt;li&gt;&lt;i&gt;3&#232;me (7/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Clignotement.html&quot; title=&quot;Clignotement&quot;&gt;clignotement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Dissipation-De-La-Magie.html&quot; title=&quot;Dissipation de la magie&quot;&gt;dissipation de la magie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Don-Des-Langues.html&quot; title=&quot;Don des langues&quot;&gt;don des langues&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lenteur.html&quot; title=&quot;Lenteur&quot;&gt;lenteur&lt;/a&gt; (DD 19)&lt;/li&gt;&lt;li&gt;&lt;i&gt;2&#232;me (8/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;C&#233;cit&#233;surdit&#233;.html&quot; title=&quot;C&#233;cit&#233;/surdit&#233;&quot;&gt;c&#233;cit&#233;/surdit&#233;&lt;/a&gt; (DD 18), &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Pens&#233;es.html&quot; title=&quot;D&#233;tection de pens&#233;es&quot;&gt;d&#233;tection de pens&#233;es&lt;/a&gt; (DD 18), &lt;a class=&quot;pagelink&quot; href=&quot;Flou.html&quot; title=&quot;Flou&quot;&gt;flou&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Trou-De-M&#233;moire.html&quot; title=&quot;Trou de m&#233;moire&quot;&gt;trou de m&#233;moire&lt;/a&gt; (DD 18), &lt;a class=&quot;pagelink&quot; href=&quot;Verrou-Du-Mage.html&quot; title=&quot;Verrou du mage&quot;&gt;verrou du mage&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;1er (8/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Mage.html&quot; title=&quot;Armure de mage&quot;&gt;armure de mage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Effacement.html&quot; title=&quot;Effacement&quot;&gt;effacement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Feuille-Morte.html&quot; title=&quot;Feuille morte&quot;&gt;feuille morte&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Identification.html&quot; title=&quot;Identification&quot;&gt;identification&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Projectile-Magique.html&quot; title=&quot;Projectile magique&quot;&gt;projectile magique&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;0 (&#224; volont&#233;)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Lecture-De-La-Magie.html&quot; title=&quot;Lecture de la magie&quot;&gt;lecture de la magie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re.html&quot; title=&quot;Lumi&#232;re&quot;&gt;lumi&#232;re&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Manipulation-&#192;-Distance.html&quot; title=&quot;Manipulation &#224; distance&quot;&gt;manipulation &#224; distance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Message.html&quot; title=&quot;Message&quot;&gt;message&lt;/a&gt;, 5 de plus&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Statistiques&lt;/div&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;For&lt;/b&gt; 38, &lt;b&gt;Dex &lt;/b&gt;11, &lt;b&gt;Con &lt;/b&gt;28, &lt;b&gt;Int&lt;/b&gt; 23, &lt;b&gt;Sag &lt;/b&gt;22, &lt;b&gt;Cha &lt;/b&gt;23&lt;/li&gt;&lt;li&gt;&lt;b&gt;BBA &lt;/b&gt;+27 ; &lt;b&gt;BMO &lt;/b&gt;+45 (+47 destruction d’arme) ; &lt;b&gt;DMD&lt;/b&gt; 57 (59 contre croc-enjambe)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; (morsure, griffe), &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Puissance.html&quot; title=&quot;Attaque en puissance&quot;&gt;Attaque en puissance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-Multiples.html&quot; title=&quot;Attaques multiples&quot;&gt;Attaques multiples&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Don-Pour-Les-Critiques.html&quot; title=&quot;Don pour les critiques&quot;&gt;Don pour les critiques&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Efficacit&#233;-Des-Sorts-Accrue.html&quot; title=&quot;Efficacit&#233; des sorts accrue&quot;&gt;Efficacit&#233; des sorts accrue&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Encha&#238;nement.html&quot; title=&quot;Encha&#238;nement&quot;&gt;Encha&#238;nement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Incantation-Rapide.html&quot; title=&quot;Incantation rapide&quot;&gt;Incantation rapide&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;flexes-Surhumains.html&quot; title=&quot;R&#233;flexes surhumains&quot;&gt;R&#233;flexes surhumains&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Savancer.html&quot; title=&quot;S&amp;#39;avancer&quot;&gt;S’avancer&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-La-Destruction.html&quot; title=&quot;Science de la destruction&quot;&gt;Science de la destruction&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l’initiative&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Critique.html&quot; title=&quot;Science du critique&quot;&gt;Science du critique&lt;/a&gt; (griffe), &lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt; (Connaissances (histoire))&lt;/li&gt;&lt;li&gt;&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; +36, &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; +36, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (g&#233;ographie, myst&#232;res, noblesse, plans, religion) +36, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (histoire) +42, &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; +36, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +36, &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; +36, &lt;a class=&quot;pagelink&quot; href=&quot;Vol.html&quot; title=&quot;Vol&quot;&gt;Vol&lt;/a&gt; +16&lt;/li&gt;&lt;li&gt;&lt;b&gt;Langues &lt;/b&gt;c&#233;leste, commun, draconique, elfe, infernal, nain, sylvestre&lt;/li&gt;&lt;li&gt;&lt;b&gt;Particularit&#233;s &lt;/b&gt;immortel, lire les fils, ne respire pas, vol stellaire&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;ul style=&quot;margin: 0 0 -10 0;margin-top: 6px;margin-bottom: 12px;&quot;&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Sid&#233;ral.html&quot; title=&quot;Les dragons sid&#233;raux&quot;&gt;dragons sid&#233;raux&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Temporel.html&quot; title=&quot;Dragon sid&#233;ral temporel&quot;&gt;dragons temporels&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;/ul&gt;&lt;i&gt;Les &#233;cailles fissur&#233;es de ce dragon cr&#233;pitent sous l’effet d’un pouvoir aussi patient que terrifiant. Certaines de ses cornes sont vieilles et fragiles tandis que d’autres sont neuves et immacul&#233;es.&lt;/i&gt;  &lt;br /&gt;&lt;br /&gt;Gardiens de l’Histoire, les dragons temporels sont les plus puissants de tous les dragons sid&#233;raux. Ils veillent et attendent, prot&#233;geant l’univers contre tous ceux qui voudraient modifier l’ordre
temporel.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
